many-calls.fixExample:
// Before: one server round trip for every item.
For Each Item In Items Do
    ProcessOneOnServer(Item);
EndDo;
// After: one call; ProcessBatchOnServer performs the loop on the server.
ProcessBatchOnServer(Items);
// Illustrative: define these application procedures; preserve results and transaction boundaries.

temp-table-index.fixExample:
// Before: a reused temporary table has no index on its join key.
SELECT S.Ref AS Ref INTO Keys FROM Catalog.Items AS S;
// After: build the index as part of materialization.
SELECT S.Ref AS Ref INTO Keys FROM Catalog.Items AS S INDEX BY Ref;
// Illustrative batch fragments; compare creation plus all consumers.

virtual-table-filter.fixExample:
// Before: restriction after virtual-table expansion.
SELECT B.Item, B.QuantityBalance
FROM AccumulationRegister.Stock.Balance(&At) AS B
WHERE B.Item = &Item
// After: pass the valid dimension restriction into the virtual table.
SELECT B.Item, B.QuantityBalance
FROM AccumulationRegister.Stock.Balance(&At, Item = &Item) AS B
// Illustrative metadata names; validate identical balance semantics.
